sys_script_client.script:
function onSubmit() {
   //Type appropriate comment here, and begin script below

   var form = g_form.isNewRecord();
   var sys=g_form.getUniqueValue();
   alert("NEW: "+form+" Type: "+typeof form);

   if (form == true){
	alert(sys);
	try{
	var ga=new GlideAjax("createcmdb");
	ga.addParam("sysparm_name","createtable");
	ga.addParam("sysof",sys);
	ga.getXMLAnswer(tables);
	}
	catch(ex){
		alert("ERROR: "+ex.message);
	}
   }
}
function tables(response){

	alert(response);

}
